module poly6_v13_8b (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg [15:0] r0;
    reg [15:0] r1;
    reg [15:0] r2;
    reg [15:0] r3;
    reg [15:0] r4;
    reg [15:0] r5;
    reg [15:0] r6;
    always @(posedge clk) begin
        if (!rst_n) begin r0 <= 16'd0; r1 <= 16'd0; r2 <= 16'd0; r3 <= 16'd0; r4 <= 16'd0; r5 <= 16'd0; r6 <= 16'd0; y <= 16'd0; end
        else begin
            r0 <= 16'd86;
            r1 <= r0 * x + 16'd73;
            r2 <= r1 * x + 16'd23;
            r3 <= r2 * x + 16'd69;
            r4 <= r3 * x + 16'd48;
            r5 <= r4 * x + 16'd52;
            r6 <= r5 * x + 16'd39;
            y <= r6 * x;
        end
    end
endmodule

